"""Isolated real-browser retail interactions; all API calls are fixtures."""
import http.server,socketserver,threading,subprocess,tempfile,json,re
from pathlib import Path
root=Path(__file__).resolve().parents[1]/'public'
harness='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/console/style.css"><div id="app"></div><div id="toasts"></div><script type="module">
localStorage.setItem('mosaic.console.locale','en');const viewer=location.search.includes('viewer'),support=location.search.includes('support');const calls=[];
const stores=[{id:'store1',name:'客户门店',profile:{region:'East',tags:['mall'],openingHours:[{weekdays:[1,2,3,4,5],start:'09:00',end:'21:00'}],closedDates:[]}}];
let campaigns=[{id:'c1',name:'客户广告',state:'draft',config:{advertiser:'Brand',product:'SKU',storeIds:['store1'],mediaId:'creative',fillerMediaId:'filler'}}];
const response={campaign:campaigns[0],delivery:{deviceReportedCompletions:7,reportedDeviceCount:2,reportedGroupCount:1,plannedGroupSpots:100,estimateLabel:'Schedule estimate only'},perStore:[{storeId:'store1',name:'=Formula Store',deviceReportedCompletions:7,reportedDeviceCount:2,reportedGroupCount:1,plannedGroupSpots:100}],deployments:[{storeId:'store1',groupId:'g1',status:'preparing'},{storeId:'store1',groupId:'g2',status:'failed'}],pos:{rows:[],comparison:{note:'No causal inference'}},survey:null,disclaimer:'Device claims, not camera evidence'};
window.fetch=async(path,options={})=>{const body=options.body?JSON.parse(options.body):{};calls.push({path,method:options.method||'GET',body});let value=[];if(path==='/api/session')value={user:{role:viewer?'viewer':support?'platform_admin':'tenant_admin',name:'用户'},tenant:{name:'Tenant'}};else if(path==='/api/overview')value={};else if(path==='/api/retail/stores')value=stores;else if(path==='/api/retail/campaigns')value=campaigns;else if(path==='/api/media')value=[{id:'creative',name:'Creative',type:'video'},{id:'filler',name:'Filler',type:'image'}];else if(path.endsWith('/submit'))campaigns[0].state='submitted';else if(path.endsWith('/review'))campaigns[0].state=body.decision;else if(path.endsWith('/publish'))campaigns[0].state='published';else if(path.endsWith('/report'))value=response;return {ok:true,json:async()=>value};};
const wait=()=>new Promise(r=>setTimeout(r,80)),find=text=>[...document.querySelectorAll('button')].find(b=>b.textContent===text),close=()=>document.querySelector('.dialog-backdrop:last-of-type .dialog-footer button')?.click();
await import('/console/app.js');await wait();find('▧Retail campaigns')?.click();if(![...document.querySelectorAll('#app,.dialog-backdrop')].map(n=>n.textContent).join(' ').includes('Store profiles'))[...document.querySelectorAll('nav button')].find(b=>b.textContent.includes('Retail campaigns')).click();await wait();
const checks={page:[...document.querySelectorAll('#app,.dialog-backdrop')].map(n=>n.textContent).join(' ').includes('Store profiles'),names:[...document.querySelectorAll('#app,.dialog-backdrop')].map(n=>n.textContent).join(' ').includes('客户门店')&&[...document.querySelectorAll('#app,.dialog-backdrop')].map(n=>n.textContent).join(' ').includes('客户广告'),mobile:document.documentElement.scrollWidth<=innerWidth};
if(support){checks.supportNoReview=!find('Review')&&!find('Publish explicitly');}else if(!viewer){find('Edit profile').click();await wait();const region=[...document.querySelectorAll('.dialog-body input')][0];region.value='South';find('Save profile').click();await wait();checks.profile=calls.some(c=>c.path==='/api/retail/stores/store1'&&c.body.region==='South'&&c.body.openingHours[0].start==='09:00'&&c.body.tags[0]==='mall');
find('Create campaign').click();await wait();checks.campaignFields=[...document.querySelectorAll('#app,.dialog-backdrop')].map(n=>n.textContent).join(' ').includes('Outside-window filler image')&&[...document.querySelectorAll('#app,.dialog-backdrop')].map(n=>n.textContent).join(' ').includes('Control stores');
const setField=(label,value)=>{const item=[...document.querySelectorAll('.dialog-body label')].find(x=>x.textContent===label);document.getElementById(item.htmlFor).value=value;};setField('Name','New campaign');setField('Advertiser','Customer brand');setField('Product / SKU','SKU2');setField('Start date','2026-11-01');setField('End date','2026-11-05');find('Save draft').click();await wait();checks.campaignPayload=calls.some(c=>c.path==='/api/retail/campaigns'&&c.method==='POST'&&c.body.advertiser==='Customer brand'&&c.body.spotSeconds===15&&c.body.cycleSeconds===300&&c.body.fillerMediaId==='filler'&&c.body.startDate==='2026-11-01');
find('Submit for review').click();await wait();checks.submitted=calls.some(c=>c.path.endsWith('/submit'));find('Review').click();await wait();document.querySelector('.dialog-body textarea').value='Human reviewed';find('Submit decision').click();await wait();checks.reviewed=calls.some(c=>c.path.endsWith('/review')&&c.body.reason==='Human reviewed');
find('Publish explicitly').click();await wait();checks.noAutoPublish=!calls.some(c=>c.path.endsWith('/publish'));checks.confirm=!!find('Confirm publish');close();
}else checks.readonly=!find('Create campaign')&&!find('Edit profile')&&!find('Publish explicitly');
find('Delivery report').click();await wait();checks.evidence=[...document.querySelectorAll('#app,.dialog-backdrop')].map(n=>n.textContent).join(' ').includes('Device-reported completions')&&[...document.querySelectorAll('#app,.dialog-backdrop')].map(n=>n.textContent).join(' ').includes('Planned group opportunities')&&[...document.querySelectorAll('#app,.dialog-backdrop')].map(n=>n.textContent).join(' ').includes('Preparing');checks.noFakePOS=document.querySelector('.dialog-body').textContent.includes('No comparable POS aggregates');checks.export=!!find('Export store CSV');if(viewer)checks.noSurveyWrite=!find('Save aggregate survey');else if(support)checks.supportNoRetry=!find('Retry failed / cancelled targets');else{document.querySelector('.dialog-body textarea').value='storeId,date,sku,units,revenue\\nstore1,2026-11-01,SKU,2,10';find('Import aggregate POS').click();await wait();checks.pos=calls.some(c=>c.path.endsWith('/pos')&&c.body.rows[0].units===2);for(const input of document.querySelectorAll('.dialog-body input[type=number]'))input.value='0';find('Save aggregate survey').click();await wait();checks.survey=calls.some(c=>c.path.endsWith('/survey')&&c.body.responses===0&&c.body.awareBase===0);find('Retry failed / cancelled targets').click();await wait();checks.retryConfirm=!!find('Confirm retry')&&!calls.some(c=>c.path.endsWith('/publish'));find('Confirm retry').click();await wait();checks.retryPayload=calls.some(c=>c.path.endsWith('/publish')&&c.body.retryFailed===true);}
document.body.append(Object.assign(document.createElement('pre'),{id:'result',hidden:true,textContent:JSON.stringify(checks)}));
</script>'''
class Handler(http.server.SimpleHTTPRequestHandler):
 def __init__(self,*args,**kwargs):super().__init__(*args,directory=str(root),**kwargs)
 def do_GET(self):
  if self.path.startswith('/retail-check'):
   self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.end_headers();self.wfile.write(harness.encode())
  else:super().do_GET()
 def log_message(self,*args):pass
with socketserver.TCPServer(('127.0.0.1',0),Handler) as server:
 threading.Thread(target=server.serve_forever,daemon=True).start()
 for route in ['/retail-check?manager','/retail-check?viewer','/retail-check?support']:
  result=subprocess.run(['node',str(root.parent/'tests/browser-runner.mjs'),f'http://127.0.0.1:{server.server_address[1]}{route}'],capture_output=True,text=True,timeout=45)
  assert result.returncode==0,result.stderr
  data=json.loads(result.stdout);print(route,data)
  assert data['viewport']['width']==390, 'Phone viewport not active'
  assert all(data['checks'].values()), 'Browser interaction failed'
 server.shutdown()
